package com.lyrashop.audit.service;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import com.lyrashop.audit.dto.AdminAuditLogResponse;import com.lyrashop.audit.entity.AdminAuditLog;import com.lyrashop.audit.repository.AdminAuditLogRepository;@Service public class AdminAuditService{private final AdminAuditLogRepository logs;public AdminAuditService(AdminAuditLogRepository logs){this.logs=logs;}@Transactional public void record(UUID adminId,String method,String path,int status,String ip,String agent){logs.save(new AdminAuditLog(adminId,method,path,status,limit(ip,64),limit(agent,500)));}@Transactional(readOnly=true)public List<AdminAuditLogResponse> list(){return logs.findTop200ByOrderByCreatedAtDescIdDesc().stream().map(AdminAuditLogResponse::from).toList();}private static String limit(String v,int n){return v==null?null:v.substring(0,Math.min(v.length(),n));}}
